  const rankDelta = direction === 'TB' ? y2 - y1 : x2 - x1;
  const normalDelta = direction === 'TB' ? x2 - x1 : y2 - y1;
  const forward = rankDelta >= 0;
  const bend = computeEdgeBend(rankDelta, normalDelta, forward);

