    if (direction === 'TB') {
      if (Math.abs(normalDelta) < 1) {
        return {
          d: `M ${x1} ${y1} L ${x2} ${y2}`,
          labelX: (x1 + x2) / 2,
          labelY: (y1 + y2) / 2 - 10,
        };
